def depth_dfs(u0=0):
	S = [u0]
	D = [-1] * N
	D[u0] = 0
	while S:
		u = S.pop()
		for v in G[u]:
			if D[v] < 0:
				D[v] = D[u] + 1
				S.append(v)
	return D

def one_value(X, t):
	res = 0
	for i in range(len(X)):
		if i & t - 1 == 0:
			res ^= X[i]

def dp_all_values(X, kmax):
	C = [X[:] for _ in range(kmax + 1)]
	for k in range(1, kmax + 1):
		for i in range(len(X)):
			C[k][i] = C[k - 1][i ^ 1 << k - 1]
			if i >> k - 1 & 1 == 0:
				C[k][i] ^= C[k - 1][i]
	return C

def main():
	global N, G
	(N, Q) = map(int, input().split())
	G = [[] for _ in range(N)]
	for _ in range(N - 1):
		(u, v) = map(int, input().split())
		G[u].append(v)
		G[v].append(u)
	X0 = list(map(int, input().split()))
	D = depth_dfs()
	MD = max(D)
	X = [0] * (MD + 1)
	for u in range(N):
		X[D[u]] ^= X0[u]
	k = 1
	while 1 << k <= MD:
		k += 1
	period = 1 << k
	while len(X) < period:
		X.append(0)
	C = dp_all_values(X, k)
	for i in range(Q):
		t = (int(input()) - 1) % period
		print(C[k][t])
main()
